// Compile: g++ -std=c++17 -I/path/to/morph.hpp -o output program.cpp

#include <iostream>
#include <vector>
#include <cmath>
#include <string>
#include <algorithm>

int main() {
    // #| label: fig-01-sim-ep0102
    // #| fig-cap: "Simulador EP01_02: Desempenho Preditivo — Métricas de ML"
    // #| echo: false
    // #| output: true

    // Simulador EP01_02: Desempenho Preditivo — Métricas de ML
    // Este simulador interativo demonstra como diferentes valores de 
    // Verdadeiros Positivos (VP), Falsos Negativos (FN), Falsos Positivos (FP)
    // e Verdadeiros Negativos (VN) afetam as métricas de avaliação de modelos
    // de Machine Learning.

    std::cout << "=== Simulador EP01_02: Desempenho Preditivo — Métricas de ML ===\n";
    std::cout << "Matriz de Confusão & Métricas\n\n";

    // Cenários pré-definidos (conforme botões do HTML)
    struct Scenario {
        std::string name;
        int vp, fn, fp, vn;
    };

    std::vector<Scenario> scenarios = {
        {"Exemplo do EP", 40, 10, 15, 35},
        {"Detector Preciso", 90, 10, 5, 95},
        {"Muitos Falsos Negativos", 50, 50, 5, 95},
        {"Muitos Falsos Positivos", 80, 5, 60, 55}
    };

    // Simulação interativa via console
    int currentScenario = 0;
    char input;

    while (true) {
        // Exibe controles simulados (equivalentes aos sliders)
        std::cout << "\n--- ENTRADAS (PARÂMETROS DA MATRIZ) ---\n";
        std::cout << "VP: " << scenarios[currentScenario].vp << " | ";
        std::cout << "FN: " << scenarios[currentScenario].fn << " | ";
        std::cout << "FP: " << scenarios[currentScenario].fp << " | ";
        std::cout << "VN: " << scenarios[currentScenario].vn << "\n\n";

        // Calcula métricas (equivalente à função update() do JavaScript)
        int vp = scenarios[currentScenario].vp;
        int fn = scenarios[currentScenario].fn;
        int fp = scenarios[currentScenario].fp;
        int vn = scenarios[currentScenario].vn;

        int tot = vp + fn + fp + vn;
        double acc = tot == 0 ? 0 : (vp + vn) / (double)tot;
        double pre = (vp + fp) == 0 ? 0 : vp / (double)(vp + fp);
        double sen = (vp + fn) == 0 ? 0 : vp / (double)(vp + fn);
        double f1  = (pre + sen) == 0 ? 0 : (2 * pre * sen) / (pre + sen);

        // Exibe a matriz de confusão (equivalente ao grid do HTML)
        std::cout << "--- MATRIZ DE CONFUSÃO DISCRETA ---\n";
        std::cout << "                Pred +    Pred −\n";
        std::cout << "Real +         VP: " << vp << "    FN: " << fn << "\n";
        std::cout << "Real −         FP: " << fp << "    VN: " << vn << "\n\n";

        // Exibe as métricas calculadas em tempo real
        std::cout << "--- MÉTRICAS CALCULADAS ---\n";
        std::cout << "Acurácia: " << (acc * 100) << "% | Fórmula: (VP + VN) / Total\n";
        std::cout << "Precisão: " << (pre * 100) << "% | Fórmula: VP / (VP + FP)\n";
        std::cout << "Sensibilidade (Recall): " << (sen * 100) << "% | Fórmula: VP / (VP + FN)\n";
        std::cout << "F1-Score: " << (f1 * 100) << "% | Fórmula: 2 · (P · R) / (P + R)\n";
        std::cout << "Total de Amostras: " << tot << "\n";

        // Barras de progresso visuais (equivalente aos elementos com background)
        auto progress_bar = [](double ratio) {
            int bar_len = 30;
            int fill_len = (int)(ratio * bar_len);
            std::string bar(bar_len, ' ');
            std::fill(bar.begin(), bar.begin() + fill_len, '█');
            return bar;
        };

        std::cout << "\nVisualização (barras de progresso):\n";
        std::cout << "Acurácia: " << progress_bar(acc) << "\n";
        std::cout << "Precisão: " << progress_bar(pre) << "\n";
        std::cout << "Sensib.:  " << progress_bar(sen) << "\n";
        std::cout << "F1-Score: " << progress_bar(f1) << "\n\n";

        // Menu interativo (equivalente aos botões de cenário e sliders)
        std::cout << "Opções:\n";
        for (size_t i = 0; i < scenarios.size(); ++i) {
            std::cout << "  [" << i+1 << "] " << scenarios[i].name << "\n";
        }
        std::cout << "  [0] Sair\n";
        std::cout << "Escolha (1-" << scenarios.size() << ", 0 para sair, ou r para reexibir): ";

        std::cin >> input;

        if (input == '0') break;
        if (input == 'r') continue;

        int choice = input - '1';
        if (choice >= 0 && choice < (int)scenarios.size()) {
            currentScenario = choice;
            std::cout << "\n>>> Cenário selecionado: " << scenarios[choice].name << "\n";
        } else {
            std::cout << "\nOpção inválida. Tente novamente.\n";
            std::cin.clear();
            std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        }

        std::cout << "\n" << std::string(50, '-') << "\n";
    }

    std::cout << "\nSimulação encerrada. Até logo!\n";
    return 0;
}

