void gerarPadraoXadrez(int L, int C) {
    // Limitando dimensões conforme especificação
    L = std::min(10, std::max(1, L));
    C = std::min(10, std::max(1, C));

    std::cout << "=== SIMULADOR EP01_09: GERADOR DE MATRIZ XADREZ ===\n";
    std::cout << "Lógica: (i + j) % 2\n\n";
    std::cout << "Dimensões: " << L << " linhas × " << C << " colunas\n\n";

    // Cabeçalho visual
    std::cout << "GRADE GRÁFICA:\n";
    for (int i = 0; i < C * 8; i++) std::cout << "-";
    std::cout << "\n";

    // Gerar e exibir a matriz
    std::vector<std::vector<int>> matriz(L, std::vector<int>(C));
    std::cout << "\nSAÍDA ESPERADA (VALORES):\n";

    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            int val = (i + j) % 2 == 0 ? 0 : 1;
            matriz[i][j] = val;
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    // Exibição gráfica simplificada (ASCII)
    std::cout << "\nGRADE GRÁFICA:\n";
    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            if (matriz[i][j] == 0) {
                std::cout << "██";  // Peça escura
            } else {
                std::cout << "░░";  // Peça clara
            }
        }
        std::cout << "\n";
    }

    // Legendas
    std::cout << "\nLegenda:";
    std::cout << "\n  ██ = 0 (escuro)";
    std::cout << "\n  ░░ = 1 (claro)";
    std::cout << "\n\n";
}

int main() {
    // Simulação interativa
    std::cout << "Simulador EP01_09: Gerador de Padrão Xadrez\n";
    std::cout << "Lógica de paridade (i + j) % 2\n\n";

    std::string input;
    int L = 5, C = 6;  // Valores padrão

    std::cout << "Digite o número de linhas (L) [1-10, padrão=5]: ";
    std::getline(std::cin, input);
    if (!input.empty()) L = std::stoi(input);

    std::cout << "Digite o número de colunas (C) [1-10, padrão=6]: ";
    std::getline(std::cin, input);
    if (!input.empty()) C = std::stoi(input);

    gerarPadraoXadrez(L, C);

    return 0;
}

