        cell.addEventListener('click', function() {
          pixels[i] = (pixels[i] + 51) % 256;
          render();
          updateStats();
        });

        grid.appendChild(cell);
      });
    }

    btnRand.addEventListener('click', function() {
      pixels = pixels.map(function(){ return Math.floor(Math.random() * 256); });
